function countTopRanges(nums: number[], k: number): number {
  const n = nums.length;
  const top = nums.reduce((a, b) => Math.max(a, b));
  let total = 0;
  for (let l = 0; l < n; l++) {
    let seen = 0;
    for (let r = l; r < n; r++) {
      if (nums[r] === top) seen++;
      if (seen >= k) { total += n - r; break; }
    }
  }
  return total;
}

